"use client";

import { describeSignOut } from "@exwave-nexus/auth/messages";
import {
  useExwave,
  useResendVerification,
  useSignIn,
} from "@exwave-nexus/auth/react";
import { type ComponentProps, type FormEvent, useId } from "react";
import { AuthLink, redirectTarget } from "@/components/exwave/auth-link";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

export function SignInForm({ className, ...props }: ComponentProps<"div">) {
  const id = useId();
  const { navigate, paths, signOutReason, messages } = useExwave();
  const signIn = useSignIn();
  const resend = useResendVerification(signIn.unverifiedEmail);
  const ended = signOutReason
    ? describeSignOut(signOutReason, { messages })
    : null;

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const session = await signIn.run({
      login: String(form.get("login")),
      password: String(form.get("password")),
    });
    if (session) navigate(redirectTarget(paths.afterSignIn), { replace: true });
  }

  return (
    <div className={cn("flex flex-col gap-6", className)} {...props}>
      <Card>
        <CardHeader>
          <CardTitle className="text-2xl">Sign in</CardTitle>
          <CardDescription>
            Enter your email or username, and your password.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={onSubmit} aria-busy={signIn.pending}>
            <div className="flex flex-col gap-6">
              {ended && (
                <p
                  role="status"
                  className={cn(
                    "rounded-md border px-3 py-2 text-sm",
                    ended.tone === "error" &&
                      "border-destructive/50 text-destructive",
                  )}
                >
                  {ended.text}
                </p>
              )}
              <div className="grid gap-2">
                <Label htmlFor={`${id}-login`}>Email or username</Label>
                <Input
                  id={`${id}-login`}
                  name="login"
                  autoComplete="username"
                  required
                />
              </div>
              <div className="grid gap-2">
                <div className="flex items-center">
                  <Label htmlFor={`${id}-password`}>Password</Label>
                  <AuthLink
                    href={paths.forgotPassword}
                    className="ml-auto text-sm underline-offset-4 hover:underline"
                  >
                    Forgot your password?
                  </AuthLink>
                </div>
                <Input
                  id={`${id}-password`}
                  name="password"
                  type="password"
                  autoComplete="current-password"
                  aria-invalid={signIn.error ? true : undefined}
                  aria-describedby={signIn.message ? `${id}-error` : undefined}
                  required
                />
              </div>
              {signIn.message && (
                <p
                  id={`${id}-error`}
                  role="alert"
                  className="text-sm text-destructive"
                >
                  {signIn.message}
                </p>
              )}
              {signIn.unverifiedEmail && (
                <Button
                  type="button"
                  variant="outline"
                  disabled={resend.pending || resend.sent}
                  onClick={() => resend.run()}
                >
                  {resend.sent
                    ? "We sent a new link"
                    : "Send a new verification link"}
                </Button>
              )}
              <Button
                type="submit"
                className="w-full"
                disabled={signIn.pending}
              >
                {signIn.pending ? "Signing in…" : "Sign in"}
              </Button>
            </div>
            <p className="mt-4 text-center text-sm">
              Don&apos;t have an account?{" "}
              <AuthLink
                href={paths.signUp}
                className="underline underline-offset-4"
              >
                Sign up
              </AuthLink>
            </p>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useExwave } from "@exwave-nexus/auth/react";
import type { ComponentProps, MouseEvent } from "react";

/** A link between auth pages that moves the way your app does (the provider's `navigate`). */
export function AuthLink({
  href,
  onClick,
  ...props
}: ComponentProps<"a"> & { href: string }) {
  const { navigate } = useExwave();
  const follow = (event: MouseEvent<HTMLAnchorElement>) => {
    onClick?.(event);
    if (
      event.defaultPrevented ||
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey ||
      props.target
    )
      return;
    event.preventDefault();
    navigate(href);
  };
  return <a href={href} onClick={follow} {...props} />;
}

/** `?redirect=/path` from the address bar when it stays on this site, else `fallback`. */
export function redirectTarget(fallback: string): string {
  if (typeof location === "undefined") return fallback;
  const to = new URLSearchParams(location.search).get("redirect");
  return to?.startsWith("/") && !to.startsWith("//") && !to.startsWith("/\\")
    ? to
    : fallback;
}

"use client";

import { describeWeakPassword } from "@exwave-nexus/auth/messages";
import {
  useExwave,
  usePasswordCheck,
  usePlatformConfig,
  useSignUp,
} from "@exwave-nexus/auth/react";
import { type ComponentProps, type FormEvent, useId, useState } from "react";
import { AuthLink } from "@/components/exwave/auth-link";
import { PasswordRules } from "@/components/exwave/password-rules";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

export function SignUpForm({ className, ...props }: ComponentProps<"div">) {
  const id = useId();
  const { paths, messages } = useExwave();
  const config = usePlatformConfig();
  const { step, email, policy, signUp, resend, back } = useSignUp();
  const [password, setPassword] = useState("");
  const [tried, setTried] = useState(false);
  const check = usePasswordCheck(password, policy);
  const weak =
    tried && !check.valid
      ? describeWeakPassword(check.failed, { policy, messages })
      : null;
  const error = weak ?? signUp.message;

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setTried(true);
    if (!check.valid) return;
    const form = new FormData(event.currentTarget);
    await signUp.run({
      displayName: String(form.get("displayName")),
      email: String(form.get("email")),
      password,
    });
  }

  if (config && !config.signUpEnabled)
    return (
      <div className={cn("flex flex-col gap-6", className)} {...props}>
        <Card>
          <CardHeader>
            <CardTitle className="text-2xl">Sign-up is closed</CardTitle>
            <CardDescription>
              New accounts are by invitation only. Already have one?{" "}
              <AuthLink
                href={paths.signIn}
                className="underline underline-offset-4"
              >
                Sign in
              </AuthLink>
            </CardDescription>
          </CardHeader>
        </Card>
      </div>
    );

  if (step === "check_email")
    return (
      <div className={cn("flex flex-col gap-6", className)} {...props}>
        <Card>
          <CardHeader>
            <CardTitle className="text-2xl">Check your email</CardTitle>
            <CardDescription>
              We sent a link to <strong>{email}</strong>. Open it to verify your
              email and sign in.
            </CardDescription>
          </CardHeader>
          <CardContent className="flex flex-col gap-3">
            {resend.message && (
              <p role="alert" className="text-sm text-destructive">
                {resend.message}
              </p>
            )}
            <Button
              variant="outline"
              disabled={resend.pending || resend.sent}
              onClick={() => resend.run()}
            >
              {resend.sent ? "We sent a new link" : "Send the link again"}
            </Button>
            <Button variant="ghost" onClick={back}>
              Use a different email
            </Button>
          </CardContent>
        </Card>
      </div>
    );

  return (
    <div className={cn("flex flex-col gap-6", className)} {...props}>
      <Card>
        <CardHeader>
          <CardTitle className="text-2xl">Create an account</CardTitle>
          <CardDescription>
            We&apos;ll email you a link to verify it.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={onSubmit} aria-busy={signUp.pending}>
            <div className="flex flex-col gap-6">
              <div className="grid gap-2">
                <Label htmlFor={`${id}-name`}>Name</Label>
                <Input
                  id={`${id}-name`}
                  name="displayName"
                  autoComplete="name"
                  required
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor={`${id}-email`}>Email</Label>
                <Input
                  id={`${id}-email`}
                  name="email"
                  type="email"
                  autoComplete="email"
                  required
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor={`${id}-password`}>Password</Label>
                <Input
                  id={`${id}-password`}
                  name="password"
                  type="password"
                  autoComplete="new-password"
                  value={password}
                  onChange={(event) => setPassword(event.target.value)}
                  aria-invalid={error ? true : undefined}
                  aria-describedby={`${id}-rules`}
                  required
                />
                <PasswordRules id={`${id}-rules`} check={check} />
              </div>
              {error && (
                <p role="alert" className="text-sm text-destructive">
                  {error}
                </p>
              )}
              <Button
                type="submit"
                className="w-full"
                disabled={signUp.pending}
              >
                {signUp.pending ? "Creating your account…" : "Sign up"}
              </Button>
            </div>
            <p className="mt-4 text-center text-sm">
              Already have an account?{" "}
              <AuthLink
                href={paths.signIn}
                className="underline underline-offset-4"
              >
                Sign in
              </AuthLink>
            </p>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import type { PasswordCheck } from "@exwave-nexus/auth/react";
import { Check, Circle } from "lucide-react";
import { cn } from "@/lib/utils";

/** The platform's password rules, ticked off as the password is typed. */
export function PasswordRules({
  check,
  id,
  className,
}: {
  check: PasswordCheck;
  id?: string;
  className?: string;
}) {
  if (check.rules.length === 0) return null;
  return (
    <ul id={id} className={cn("grid gap-1 text-sm", className)}>
      {check.rules.map(({ rule, ok, label }) => (
        <li
          key={rule}
          className={cn(
            "flex items-center gap-2",
            ok ? "text-foreground" : "text-muted-foreground",
          )}
        >
          {ok ? (
            <Check className="size-3.5" aria-hidden="true" />
          ) : (
            <Circle className="size-3.5" aria-hidden="true" />
          )}
          <span>
            {label}
            <span className="sr-only">{ok ? " (done)" : " (needed)"}</span>
          </span>
        </li>
      ))}
    </ul>
  );
}

"use client";

import { useEmailLink, useExwave } from "@exwave-nexus/auth/react";
import { type ComponentProps, useEffect } from "react";
import { AuthLink } from "@/components/exwave/auth-link";
import {
  Card,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { cn } from "@/lib/utils";

/** The page verification emails link to: verifies, signs in, then moves on. */
export function VerifyEmail({ className, ...props }: ComponentProps<"div">) {
  const { navigate, paths } = useExwave();
  const link = useEmailLink();

  useEffect(() => {
    if (link.status === "verified")
      navigate(paths.afterSignIn, { replace: true });
  }, [link.status, navigate, paths.afterSignIn]);

  const [title, description] =
    link.status === "error"
      ? ["This link didn't work", link.message]
      : link.status === "none"
        ? [
            "Verify your email",
            "Open this page from the link in your verification email.",
          ]
        : link.status === "verified"
          ? ["Email verified", "You're signed in."]
          : ["Verifying your email…", "This only takes a moment."];

  return (
    <div className={cn("flex flex-col gap-6", className)} {...props}>
      <Card>
        <CardHeader>
          <CardTitle className="text-2xl" role="status">
            {title}
          </CardTitle>
          <CardDescription>
            {description}{" "}
            {(link.status === "error" || link.status === "none") && (
              <AuthLink
                href={paths.signIn}
                className="underline underline-offset-4"
              >
                Go to sign in
              </AuthLink>
            )}
          </CardDescription>
        </CardHeader>
      </Card>
    </div>
  );
}

"use client";

import { useExwave, usePasswordReset } from "@exwave-nexus/auth/react";
import { type ComponentProps, type FormEvent, useId, useState } from "react";
import { AuthLink } from "@/components/exwave/auth-link";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

export function ForgotPasswordForm({
  className,
  ...props
}: ComponentProps<"div">) {
  const id = useId();
  const { paths } = useExwave();
  const { request } = usePasswordReset();
  const [email, setEmail] = useState("");

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    await request.run(email);
  }

  return (
    <div className={cn("flex flex-col gap-6", className)} {...props}>
      <Card>
        <CardHeader>
          <CardTitle className="text-2xl">
            {request.sent ? "Check your email" : "Reset your password"}
          </CardTitle>
          <CardDescription>
            {request.sent
              ? `If an account uses ${email}, we sent it a link to choose a new password.`
              : "Enter your email and we'll send you a link to choose a new password."}
          </CardDescription>
        </CardHeader>
        {!request.sent && (
          <CardContent>
            <form onSubmit={onSubmit} aria-busy={request.pending}>
              <div className="flex flex-col gap-6">
                <div className="grid gap-2">
                  <Label htmlFor={`${id}-email`}>Email</Label>
                  <Input
                    id={`${id}-email`}
                    type="email"
                    autoComplete="email"
                    value={email}
                    onChange={(event) => setEmail(event.target.value)}
                    required
                  />
                </div>
                {request.message && (
                  <p role="alert" className="text-sm text-destructive">
                    {request.message}
                  </p>
                )}
                <Button
                  type="submit"
                  className="w-full"
                  disabled={request.pending}
                >
                  {request.pending ? "Sending…" : "Send the link"}
                </Button>
              </div>
              <p className="mt-4 text-center text-sm">
                Remembered it?{" "}
                <AuthLink
                  href={paths.signIn}
                  className="underline underline-offset-4"
                >
                  Sign in
                </AuthLink>
              </p>
            </form>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

"use client";

import { describeWeakPassword } from "@exwave-nexus/auth/messages";
import {
  useEmailLink,
  useExwave,
  usePasswordCheck,
  usePasswordReset,
} from "@exwave-nexus/auth/react";
import { type ComponentProps, type FormEvent, useId, useState } from "react";
import { AuthLink } from "@/components/exwave/auth-link";
import { PasswordRules } from "@/components/exwave/password-rules";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

/** The page password reset emails link to: choose a new password, then sign in. */
export function ResetPasswordForm({
  className,
  ...props
}: ComponentProps<"div">) {
  const id = useId();
  const { navigate, paths, messages } = useExwave();
  const link = useEmailLink();
  const { confirm, policy } = usePasswordReset();
  const [password, setPassword] = useState("");
  const [tried, setTried] = useState(false);
  const check = usePasswordCheck(password, policy);
  const error =
    tried && !check.valid
      ? describeWeakPassword(check.failed, { policy, messages })
      : confirm.message;

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setTried(true);
    if (link.status !== "reset" || !check.valid) return;
    const session = await confirm.run(
      { userId: link.userId, code: link.code },
      password,
    );
    if (session) navigate(paths.afterSignIn, { replace: true });
  }

  if (link.status === "loading") return null;

  return (
    <div className={cn("flex flex-col gap-6", className)} {...props}>
      <Card>
        <CardHeader>
          <CardTitle className="text-2xl">Choose a new password</CardTitle>
          <CardDescription>
            {link.status === "reset" ? (
              "You'll be signed in once it's saved."
            ) : (
              <>
                Open this page from the link in your password reset email.{" "}
                <AuthLink
                  href={paths.forgotPassword}
                  className="underline underline-offset-4"
                >
                  Send a new link
                </AuthLink>
              </>
            )}
          </CardDescription>
        </CardHeader>
        {link.status === "reset" && (
          <CardContent>
            <form onSubmit={onSubmit} aria-busy={confirm.pending}>
              <div className="flex flex-col gap-6">
                <div className="grid gap-2">
                  <Label htmlFor={`${id}-password`}>New password</Label>
                  <Input
                    id={`${id}-password`}
                    type="password"
                    autoComplete="new-password"
                    value={password}
                    onChange={(event) => setPassword(event.target.value)}
                    aria-invalid={error ? true : undefined}
                    aria-describedby={`${id}-rules`}
                    required
                  />
                  <PasswordRules id={`${id}-rules`} check={check} />
                </div>
                {error && (
                  <p role="alert" className="text-sm text-destructive">
                    {error}
                  </p>
                )}
                <Button
                  type="submit"
                  className="w-full"
                  disabled={confirm.pending}
                >
                  {confirm.pending ? "Saving…" : "Save and sign in"}
                </Button>
              </div>
            </form>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

"use client";

import { useExwave, useSignOut } from "@exwave-nexus/auth/react";
import type { ComponentProps } from "react";
import { Button } from "@/components/ui/button";

/** Signs out here, or on every device with `everywhere`, then goes to `paths.afterSignOut`. */
export function SignOutButton({
  everywhere = false,
  children,
  ...props
}: ComponentProps<typeof Button> & { everywhere?: boolean }) {
  const { navigate, paths } = useExwave();
  const signOut = useSignOut();
  return (
    <Button
      variant="outline"
      disabled={signOut.pending}
      title={signOut.message ?? undefined}
      onClick={async () => {
        await signOut.run({ everywhere });
        navigate(paths.afterSignOut, { replace: true });
      }}
      {...props}
    >
      {children ?? (everywhere ? "Sign out everywhere" : "Sign out")}
    </Button>
  );
}

"use client";

import { useExwave, useSignOut } from "@exwave-nexus/auth/react";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

const initials = (name: string) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase())
    .join("") || "?";

/** "Sign in" when signed out; the user's menu when signed in. */
export function UserButton({
  accountHref = "/account",
}: {
  accountHref?: string;
}) {
  const { isLoaded, user, navigate, paths } = useExwave();
  const signOut = useSignOut();

  if (!isLoaded) return null;
  if (!user)
    return (
      <Button
        variant="outline"
        size="sm"
        onClick={() => navigate(paths.signIn)}
      >
        Sign in
      </Button>
    );

  const leave = async (everywhere: boolean) => {
    await signOut.run({ everywhere });
    navigate(paths.afterSignOut, { replace: true });
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className="rounded-full"
          aria-label="Your account"
        >
          <Avatar>
            <AvatarFallback>{initials(user.displayName)}</AvatarFallback>
          </Avatar>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-56">
        <DropdownMenuLabel className="flex flex-col">
          <span>{user.displayName}</span>
          <span className="text-muted-foreground text-xs font-normal">
            {user.email}
          </span>
        </DropdownMenuLabel>
        <DropdownMenuSeparator />
        <DropdownMenuItem onSelect={() => navigate(accountHref)}>
          Account
        </DropdownMenuItem>
        <DropdownMenuItem onSelect={() => leave(false)}>
          Sign out
        </DropdownMenuItem>
        <DropdownMenuItem onSelect={() => leave(true)}>
          Sign out everywhere
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
